import{_ as a,g as t,e as n,a4 as i}from"./chunks/framework.CEYJDsBW.js";const h=JSON.parse('{"title":"AnvilEvent","description":"","frontmatter":{},"headers":[],"relativePath":"en/anvilcraft/26.1/events/anvil-event.md","filePath":"en/anvilcraft/26.1/events/anvil-event.md"}'),l={name:"en/anvilcraft/26.1/events/anvil-event.md"};function r(o,e,c,d,v,s){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="anvilevent" tabindex="-1">AnvilEvent <a class="header-anchor" href="#anvilevent" aria-label="Permalink to &quot;AnvilEvent&quot;">​</a></h1><p>When performing a single operation at a landing position, distinguish an entire giant anvil from individual hit blocks. Normal <code>OnLand</code> provides the anvil&#39;s landing position, with the pressed block at <code>getPos().below()</code>. After a giant anvil lands, <code>GiantOnLand</code> fires once, followed by nine <code>OnLand</code> events across the 3 × 3 base; subscribe to the former when settling once for the whole structure. The anvil hammer also has a path that posts <code>OnLand</code> using a temporary entity.</p><p>The poster for normal falling anvils reads the flag corresponding to <code>OnLand.setAnvilDamage(true)</code> and updates the landing spot via the anvil damage flow; the giant anvil&#39;s nine notifications do not perform this read-back. <code>CollisionBlock</code> reports a collision after movement finishes, where <code>speed</code> is the length of the movement vector before collision. Canceling it blocks subsequent built-in collision crafting listeners, though already-executed entity movement cannot be undone by it. <code>HurtEntity</code> provides the target and damage value as read-only fields. <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/event/FallingBlockCollisionEventListener.java" target="_blank" rel="noreferrer">Collision handling</a> · <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java" target="_blank" rel="noreferrer">Giant anvil landing</a></p><table tabindex="0"><thead><tr><th>Event Type</th><th>Construction Site</th></tr></thead><tbody><tr><td><code>AnvilEvent</code></td><td>No direct construction call site under this name in this commit</td></tr><tr><td><code>AnvilEvent.OnLand</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java#L292" target="_blank" rel="noreferrer"><code>GiantAnvilBlock:292</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingSpectralBlockEntity.java#L105" target="_blank" rel="noreferrer"><code>FallingSpectralBlockEntity:105</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/item/tool/AnvilHammerItem.java#L197" target="_blank" rel="noreferrer"><code>AnvilHammerItem:197</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/FallingBlockEntityMixin.java#L420" target="_blank" rel="noreferrer"><code>FallingBlockEntityMixin:420</code></a></td></tr><tr><td><code>AnvilEvent.CollisionBlock</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/EntityMixin.java#L308" target="_blank" rel="noreferrer"><code>EntityMixin:308</code></a></td></tr><tr><td><code>AnvilEvent.GiantOnLand</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/block/workstation/GiantAnvilBlock.java#L288" target="_blank" rel="noreferrer"><code>GiantAnvilBlock:288</code></a></td></tr><tr><td><code>AnvilEvent.HurtEntity</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/entity/FallingSpectralBlockEntity.java#L271" target="_blank" rel="noreferrer"><code>FallingSpectralBlockEntity:271</code></a>, <a href="https://github.com/Anvil-Dev/AnvilCraft/blob/7ac05a76988c98454c0384513fcab44d9da4cf88/src/main/java/dev/dubhe/anvilcraft/mixin/FallingBlockEntityMixin.java#L461" target="_blank" rel="noreferrer"><code>FallingBlockEntityMixin:461</code></a></td></tr></tbody></table>',4)])])}const b=a(l,[["render",r]]);export{h as __pageData,b as default};
